import { CreateChart } from "../CreateChart";
import { StatisticsTable } from "../../DataTable/DataTableBase";
import { DataTablesConfigurationStats } from "../../DataTable/DataTableWrapper";
import { Max, Quantile } from "../../DataProcessing/Statistics";
import { ComputeStatisticalMeasures, ExtractFailedCount, ExtractStatusMessages, GetStatusKeys } from "../../DataProcessing/ChartsComputations/ComputeChartData";
/**
 * How many times larger the largest value may be than the typical average before the bars of the other values
 * are too small to see on a linear scale.
 */
const EXTREME_VALUE_FACTOR = 1e6;
/**
 * Whether a few values are so much larger than the rest that a linear scale hides the rest: the largest maximum
 * (or the minimum, for negative values) is more than a million times the median of the averages in size.
 * Infinite and NaN values do not count.
 *
 * @param statistics - The statistics of every solver.
 */
export function HasExtremeValues(statistics) {
    const averages = statistics
        .map((solver) => solver.avgValue)
        .filter((value) => Number.isFinite(value));
    // The size of a value is its distance from 0, so a very negative minimum counts as much as a very large maximum.
    const sizes = statistics
        .flatMap((solver) => [solver.maxValue, solver.minValue])
        .filter((value) => Number.isFinite(value))
        .map((value) => Math.abs(value));
    if (averages.length === 0 || sizes.length === 0) {
        return false;
    }
    const typical = Math.abs(Quantile(averages, 0.5));
    return typical > 0 && Max(sizes) / typical > EXTREME_VALUE_FACTOR;
}
/**
 * This function prepares and plots data by a specific category.
 *
 * @param {TraceData[]} traceData - Array of objects containing the result data.
 * @param {string} category - The category by which the data should be analyzed.
 * @param {string} title - The title of the chart.
 * @param {boolean} logScale - Whether the values are shown on a logarithmic scale. Values of 0 or less are not shown then.
 * @param {string} extremeValuesHint - Added to the subtitle when a few extreme values stretch a linear scale.
 */
export function PlotDataByCategory(traceData, category, title, defaultTime, filterType, subtitle, logScale = false, extremeValuesHint) {
    const data = ComputeStatisticalMeasures(traceData, category, defaultTime, filterType);
    // The virtual solvers are shown as lines, not as bars.
    const solverStatistics = Object.entries(data).filter(([name]) => name !== "Virtual Best Solver" && name !== "Virtual Worst Solver");
    const solverNames = solverStatistics.map(([name]) => name);
    const averageData = {
        label: "Average",
        data: solverStatistics.map(([, statistics]) => statistics.avgValue),
        borderColor: "#007bff",
        backgroundColor: "#007bffAA"
    };
    const minData = {
        label: "Min",
        data: solverStatistics.map(([, statistics]) => statistics.minValue),
        borderColor: "#28a745",
        backgroundColor: "#28a745AA"
    };
    const maxData = {
        label: "Max",
        data: solverStatistics.map(([, statistics]) => statistics.maxValue),
        borderColor: "#dc3545",
        backgroundColor: "#dc3545AA"
    };
    const stdData = {
        label: "Std",
        data: solverStatistics.map(([, statistics]) => statistics.stdValue),
        borderColor: "#6f42c1",
        backgroundColor: "#6f42c1AA"
    };
    const chartData = [averageData, minData, maxData, stdData];
    const scaleOptions = {
        x: {
            title: {
                display: true,
                text: "Solver name"
            }
        },
        y: {
            // A logarithmic scale cannot show 0 or less, so the chart does not start at 0 then.
            ...(logScale ? { type: "logarithmic" } : {}),
            title: {
                display: true,
                text: "Count"
            }
        }
    };
    const zoomOptions = {
        pan: {
            enabled: false
        },
        zoom: {
            wheel: {
                enabled: true
            },
            pinch: {
                enabled: true
            },
            mode: "y",
            scaleMode: "y"
        },
        ...(logScale ? {} : { limits: { y: { min: 0 } } })
    };
    let annotationOptions = undefined;
    /**
     * Draw annotations for the virtual best and worst solvers if SolverTime is used.
     */
    const virtualBest = data["Virtual Best Solver"];
    const virtualWorst = data["Virtual Worst Solver"];
    if (category === "SolverTime" && virtualBest && virtualWorst) {
        annotationOptions = {
            annotations: {
                line1: {
                    type: "line",
                    yMin: virtualBest.avgValue,
                    yMax: virtualBest.avgValue,
                    borderColor: "rgb(124,252,0)",
                    borderShadowColor: "rgba(0,0,0, 0)",
                    shadowOffsetY: 2,
                    borderWidth: 2,
                    label: {
                        content: "Virtual Best Average",
                        display: true,
                        position: "end"
                    }
                },
                line2: {
                    type: "line",
                    yMin: virtualWorst.avgValue,
                    yMax: virtualWorst.avgValue,
                    borderColor: "rgb(255, 99, 132)",
                    borderShadowColor: "rgba(0,0,0, 0)",
                    shadowOffsetY: 2,
                    borderWidth: 2,
                    label: {
                        content: "Virtual Worst Average",
                        display: true,
                        position: "end"
                    }
                }
            }
        };
    }
    CreateChart("bar", chartData, solverNames, title, scaleOptions, zoomOptions, annotationOptions, !logScale &&
        extremeValuesHint &&
        HasExtremeValues(solverStatistics.map(([, statistics]) => statistics))
        ? [subtitle, extremeValuesHint].filter(Boolean).join(" ")
        : subtitle);
    StatisticsTable(data, title);
    DataTablesConfigurationStats("#statisticsTable_inner");
    return chartData;
}
/**
 * This function prepares and plots all the termination status messages per solver.
 *
 * @param {TraceData[]} traceData - Array of objects containing the result data.
 * @param {string} statusType - The status type to be analyzed.
 * @param {string} title - The title of the chart.
 */
export function PlotStatusMessages(traceData, statusType, title) {
    const data = ExtractStatusMessages(traceData, statusType);
    const solverNames = data.map((obj) => {
        return obj["SolverName"];
    });
    const statusKeys = GetStatusKeys(data);
    const colorMapping = {
        Optimal: "#d5fa87",
        "Locally Optimal": "#778c4a",
        Unbounded: "#3131cc",
        Infeasible: "#05055c",
        "Locally Infeasible": "#15153b",
        "Intermediate Infeasible": "#23232e",
        "Feasible Solution": "#767694",
        "Integer Solution": "#ee02fa",
        "Intermediate Non-integer": "#883c8c",
        "Integer Infeasible": "#a671a8",
        "Lic Problem - No Solution": "#616060",
        "Error Unknown": "#0a0a0a",
        "Error No Solution": "#f5a2a3",
        "No Solution Returned": "#381414",
        "Solved Unique": "#30f522",
        Solved: "#92ff8a",
        "Solved Singular": "#085202",
        "Unbounded - No Solution": "#ff1c03",
        "Infeasible - No Solution": "#fa9287"
    };
    // A status without a color of its own, like the solver statuses, gets one from the palette of the chart.
    const chartData = statusKeys.map((key) => {
        const color = colorMapping[key];
        return {
            label: key,
            data: data.map((obj) => {
                return Number(obj[key]) || 0;
            }),
            ...(color === undefined
                ? {}
                : { borderColor: color, backgroundColor: color })
        };
    });
    const scaleOptions = {
        x: {
            title: {
                display: true,
                text: "Solver name"
            }
        },
        y: {
            title: {
                display: true,
                text: "Termination count"
            }
        }
    };
    const zoomOptions = {
        pan: {
            enabled: false
        },
        zoom: {
            wheel: {
                enabled: true
            },
            pinch: {
                enabled: true
            },
            mode: "y"
        },
        limits: {
            y: { min: 0 }
        }
    };
    CreateChart("bar", chartData, solverNames, title, scaleOptions, zoomOptions);
    return chartData;
}
/**
 * This function prepares and plots the fail count per solver.
 * @param {TraceData[]} traceData - Array of objects containing the result data.
 */
export function PlotFailCount(traceData) {
    const data = ExtractFailedCount(traceData);
    const solverNames = data.map((obj) => {
        return obj["SolverName"];
    });
    const statusKeys = GetStatusKeys(data);
    const chartData = statusKeys.map((key) => {
        return {
            label: key,
            data: data.map((obj) => {
                return Number(obj[key]) || 0;
            }),
            borderColor: "#f5a2a3",
            backgroundColor: "#f5a2a3"
        };
    });
    const scaleOptions = {
        x: {
            title: {
                display: true,
                text: "Solver name"
            }
        },
        y: {
            title: {
                display: true,
                text: "Count"
            }
        }
    };
    const zoomOptions = {
        pan: {
            enabled: false
        },
        zoom: {
            wheel: {
                enabled: true
            },
            pinch: {
                enabled: true
            },
            mode: "y"
        },
        limits: {
            y: { min: 0 }
        }
    };
    CreateChart("bar", chartData, solverNames, "Number of failed instances", scaleOptions, zoomOptions);
    return chartData;
}
